const toggle=document.querySelector('.menu-toggle');const mobile=document.querySelector('.mobile-nav');mobile.innerHTML=document.querySelector('.desktop-nav').innerHTML+'<a href="https://app.zenbu.bet">Log in</a>';function closeMenu(){mobile.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu')}toggle.addEventListener('click',()=>{const open=mobile.hidden;mobile.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close menu':'Open menu')});mobile.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
// Consent-free instrumentation hooks only. No analytics vendor or network collector is loaded.
const initialParams=new URLSearchParams(location.search);const campaign={};for(const key of ['utm_source','utm_medium','utm_campaign','utm_content','utm_term']){if(initialParams.has(key))campaign[key]=initialParams.get(key).slice(0,150)}
function track(event,details={}){const payload={event,...details,campaign,page:location.pathname,device:matchMedia('(max-width:850px)').matches?'mobile':'desktop'};window.dispatchEvent(new CustomEvent('zenbu:analytics',{detail:payload}));if(Array.isArray(window.dataLayer))window.dataLayer.push(payload)}
let referral='';try{referral=document.referrer?new URL(document.referrer).hostname:''}catch{}track('page_view',{referral});const pageStarted=Date.now();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')track('page_engagement',{seconds:Math.round((Date.now()-pageStarted)/1000)})});
document.querySelectorAll('a[href^="https://app.zenbu.bet"]').forEach(a=>{const url=new URL(a.href);for(const [k,v] of Object.entries(campaign))url.searchParams.set(k,v);url.searchParams.set('zenbu_entry',a.dataset.event||'navigation');a.href=url.toString()});document.addEventListener('click',e=>{const a=e.target.closest('[data-event]');if(a)track(a.dataset.event,{destination:a.getAttribute('href')})});
const seen=new Set();const engagement=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting&&!seen.has(e.target.id)){seen.add(e.target.id);track('section_engagement',{section:e.target.id})}}},{threshold:.2});document.querySelectorAll('main section[id]').forEach(x=>engagement.observe(x));
const reduced=matchMedia('(prefers-reduced-motion:reduce)');const story=document.querySelector('.markets-story'),sticky=document.querySelector('.markets-sticky'),trackEl=document.querySelector('.market-track');let pending=false,completed=false,currentPanel=0;const depths=new Set();
function updateScroll(){pending=false;const doc=document.documentElement;const depth=Math.round(100*scrollY/Math.max(1,doc.scrollHeight-innerHeight));for(const d of [25,50,75,100])if(depth>=d&&!depths.has(d)){depths.add(d);track('scroll_depth',{percent:d})}if(reduced.matches)return;const top=parseFloat(getComputedStyle(sticky).top)||0;const progress=Math.max(0,Math.min(1,(scrollY-story.offsetTop+top)/(story.offsetHeight-sticky.offsetHeight)));trackEl.style.transform=`translate3d(${-progress*200}%,0,0)`;const index=Math.round(progress*2);if(index!==currentPanel){currentPanel=index;document.querySelectorAll('[data-panel]').forEach((b,i)=>{b.classList.toggle('active',i===index);if(i===index)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')})}if(progress>.98&&!completed){completed=true;track('markets_sequence_complete')}}
function scheduleScroll(){if(!pending){pending=true;requestAnimationFrame(updateScroll)}}addEventListener('scroll',scheduleScroll,{passive:true});addEventListener('resize',scheduleScroll);reduced.addEventListener('change',()=>{if(reduced.matches)trackEl.style.transform='none';updateScroll()});updateScroll();
function goPanel(index){if(reduced.matches){document.querySelectorAll('.story-panel')[index].scrollIntoView();return}const top=parseFloat(getComputedStyle(sticky).top)||0;scrollTo({top:story.offsetTop-top+(story.offsetHeight-sticky.offsetHeight)*index/2,behavior:'smooth'})}document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>goPanel(Number(b.dataset.panel))));document.querySelectorAll('[data-go-panel]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();goPanel(Number(a.dataset.goPanel))}));
const demo=document.querySelector('#demo-content');let step=0;const demoTemplates=[`<span class="demo-label">STEP 01 / CREATE</span><h4 style="margin-top:20px">Weekend Rugby</h4><p>Start with something your group cares about.</p><span class="demo-label-field">YOUR QUESTION</span><div class="fake-input">Will South Africa win on Saturday?</div><div class="demo-meta"><span>Answer type</span><span>Yes / No</span></div><div class="demo-meta"><span>Prediction deadline</span><span>Saturday · 16:00 SAST</span></div>`,`<span class="demo-label">STEP 02 / INVITE</span><h4 style="margin-top:20px">Better with your people.</h4><p>Share a private invitation with the crew.</p><div class="invite-link">app.zenbu.bet / invite / rugby-crew<br><small>Illustrative invitation</small></div><div class="demo-members"><span>Sarah ✓</span><span>Michael ✓</span><span>Etienne ✓</span><span>Johan ✓</span></div><p style="margin-top:18px">8 friends. One place to settle it.</p>`,`<span class="demo-label">STEP 03 / PREDICT</span><h4 style="margin-top:20px">Will South Africa win on Saturday?</h4><p>Try picking a side in this preview.</p><div class="outcomes demo-choice"><button class="yes" data-choice="Yes" aria-pressed="false">YES</button><button class="no" data-choice="No" aria-pressed="false">NO</button></div><p class="demo-feedback" role="status">Your demo prediction stays on this page.</p><div class="demo-meta"><span>Predictions lock</span><span>Saturday · 16:00 SAST</span></div>`,`<span class="demo-label">STEP 04 / RESOLVE</span><h4 style="margin-top:20px">The result is in.</h4><p>In this example, South Africa wins. The outcome follows the official tournament result.</p><div class="demo-result"><span>✓ &nbsp; Resolved</span><strong>YES</strong></div><div class="demo-meta"><span>Scoring rule</span><span>2 points per correct answer</span></div><p style="margin-top:20px">Each prediction is recorded before the deadline.</p>`,`<span class="demo-label">STEP 05 / LEADERBOARD</span><h4 style="margin-top:20px">Sarah called it.</h4><p>Weekend Rugby · example final standings</p><div class="leaderboard">${[['Sarah','18'],['Michael','16'],['Etienne','14'],['Johan','12']].map((p,i)=>`<div><span>0${i+1}</span><span class="avatar ${i%2?'purple-avatar':''}">${p[0][0]}</span><b>${p[0]}</b><strong>${p[1]} <small>PTS</small></strong></div>`).join('')}</div>`];
function showStep(n){step=n;demo.innerHTML=demoTemplates[n];document.querySelectorAll('[data-step]').forEach((b,i)=>{b.classList.toggle('selected',i===n);b.setAttribute('aria-pressed',String(i===n))});document.querySelector('#demo-next').textContent=n===4?'Replay demo ↺':'Next step →';track('private_demo_step',{step:n+1})}document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>showStep(Number(b.dataset.step))));document.querySelector('#demo-next').addEventListener('click',()=>showStep((step+1)%5));demo.addEventListener('click',e=>{const b=e.target.closest('[data-choice]');if(!b)return;demo.querySelectorAll('[data-choice]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b))});demo.querySelector('.demo-feedback').textContent=`You picked ${b.dataset.choice}. Demo only — no prediction has been submitted.`;track('private_demo_prediction',{choice:b.dataset.choice})});showStep(0);
const wallet=document.querySelector('#wallet-content');function setWallet(name){document.querySelectorAll('[data-wallet]').forEach(b=>{const active=b.dataset.wallet===name;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active)wallet.setAttribute('aria-labelledby',b.id)});const rows=name==='activity'?[['↗','Prediction settlement','Illustrative transaction','+R420.00',true],['↗','Airtime','Illustrative purchase','−R100.00',false],['✳','Reward','Illustrative reward','+R25.00',true]]:[['◎','Available','Example eligible balance','R1,842.50',true],['◷','Reserved','Example unsettled positions','R420.00',false],['✳','Rewards','Example rewards balance','R85.00',true]];wallet.innerHTML=rows.map(r=>`<div class="transaction ${r[4]?'positive':''}"><span class="transaction-icon">${r[0]}</span><div>${r[1]}<small>${r[2]}</small></div><strong>${r[3]}</strong></div>`).join('')}const walletTabs=[...document.querySelectorAll('[data-wallet]')];walletTabs.forEach((b,i)=>{b.addEventListener('click',()=>{setWallet(b.dataset.wallet);track('wallet_preview',{tab:b.dataset.wallet})});b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?1:1-i;setWallet(walletTabs[next].dataset.wallet);walletTabs[next].focus()}})});setWallet('activity');
const products={airtime:['R100 airtime','R1,742.50'],data:['Data bundle','Pricing to be confirmed'],gaming:['R250 gaming voucher','R1,592.50'],shopping:['R500 shopping voucher','R1,342.50']};document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-product]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});const p=products[b.dataset.product];document.querySelector('#spend-description').innerHTML=`Zenbu Wallet <b>R1,842.50</b> <i>→</i> ${p[0]} <i>→</i> ${b.dataset.product==='data'?'':'Balance after purchase'} <b>${p[1]}</b>`;track('marketplace_preview',{product:b.dataset.product})}));document.querySelector('#copyright-year').textContent=new Date().getFullYear();
// Keyboard focus on a story link also brings its panel into view.
document.querySelectorAll('.story-panel').forEach((panel,i)=>panel.addEventListener('focusin',()=>{if(!reduced.matches&&getComputedStyle(sticky).position==='sticky')goPanel(i)}));
